@app.route('/')
def home():
    return """<html dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<link href="https://fonts.googleapis.com/css2?family=Cairo:wght@700;900&family=JetBrains+Mono:wght@700;900&display=swap" rel="stylesheet"><style>
*{box-sizing:border-box}body{margin:0;background:#080E1E;color:#e2e8f0;font-family:'Cairo'}
.docbar{display:flex;justify-content:space-between;padding:10px 12px;background:#101D35;border:1.5px solid #38bdf8;border-radius:12px;margin:8px;font-size:12px;font-weight:900;color:#7dd3fc;box-shadow:0 0 15px #38bdf822}
.docbar.heal{border-color:#22d3ee;box-shadow:0 0 20px #22d3ee44;animation:pulse 1s infinite}@keyframes pulse{0%,100%{opacity:1}50%{opacity:0.7}}
.panel{background:#111C33;border:1.5px solid #1e3a8a;border-radius:14px;margin:8px;padding:12px;box-shadow:0 4px 20px #0005}
.panel h3{margin:0 0 10px;font-size:14px;color:#38bdf8;text-align:center;letter-spacing:0.5px}
.ctrls{display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:10px}
.ctrl{background:#0f1a2f;border:1px solid #1e3a5f;border-radius:12px;padding:10px;text-align:center}
.ctrl label{font-size:11px;color:#94a3b8;display:block;margin-bottom:6px}
.ctrl input{width:100%;background:#020617;border:1.5px solid #38bdf8;border-radius:8px;color:#fff;font-family:'JetBrains Mono';font-weight:900;text-align:center;padding:8px;font-size:16px;direction:ltr}
.header{display:flex;gap:8px;justify-content:center;padding:10px;background:#080E1E;flex-wrap:wrap}
.hbtn{border:none;border-radius:24px;padding:10px 16px;font-family:'Cairo';font-size:12px;font-weight:900;cursor:pointer;box-shadow:0 2px 10px #0004;transition:0.2s}
.hbtn:hover{transform:translateY(-2px);box-shadow:0 4px 15px #0006}
.hbtn.orange{background:#f59e0b;color:#000}.hbtn.yellow{background:#fde047;color:#000}.hbtn.red{background:#e11d48;color:#fff}.hbtn.green{background:#22c55e;color:#000}.hbtn.blue{background:#38bdf8;color:#000}.hbtn.purple{background:#a78bfa;color:#000}.hbtn.cyan{background:#22d3ee;color:#000}
.cards{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;padding:8px;background:#080E1E}
.c{background:#111C33;border:1.5px solid #1e3a5f;border-radius:14px;padding:10px 4px;text-align:center;box-shadow:0 2px 10px #0003}
.c.gold{border-color:#facc15;box-shadow:0 0 20px #facc1530}
.c.ph{border-color:#38bdf8;background:#0f1f3a}
.l{font-size:11px;color:#94a3b8;margin-bottom:4px}
.v{font-family:'JetBrains Mono';font-size:18px;font-weight:900;direction:ltr;letter-spacing:0.5px}
.v.w{color:#f8fafc}.v.g{color:#22c55e}.v.r{color:#38bdf8}.v.y{color:#facc15}
.table{margin:8px;border-radius:14px;overflow:hidden;border:1.5px solid #1e3a5f;box-shadow:0 4px 15px #0003}
.thead{display:grid;padding:10px 12px;font-size:12px;font-weight:900;color:#e2e8f0;background:#1e293b}
.row{display:grid;padding:10px 12px;font-size:13px;background:#0f172a;border-top:1px solid #1e293b;align-items:center}
.row div{text-align:center;font-family:'JetBrains Mono';font-weight:800;direction:ltr;font-size:14px}
.badge{border-radius:14px;padding:4px 12px;font-size:11px;font-weight:900;display:inline-block;direction:ltr;font-family:'JetBrains Mono'}
.badge.green{background:#22c55e;color:#000}.badge.orange{background:#fb923c;color:#000}.badge.cyan{background:#22d3ee;color:#000}.badge.gold{background:#facc15;color:#000}.badge.blue{background:#38bdf8;color:#000}
.status{padding:8px 12px;font-size:11px;background:#020617;color:#7dd3fc;border-top:1px solid #1e293b;display:flex;justify-content:space-between;font-family:'JetBrains Mono';direction:ltr}
.num{font-family:'JetBrains Mono';font-weight:900;direction:ltr;color:#fff;letter-spacing:0.5px}
</style></head><body>
<div class="docbar" id="docbar"><span id="elapsed">0s</span><span id="rate">V96 MOL3A</span><span id="profit">+0.00$</span><span id="healed">0 healed</span><span id="spec">READY</span></div>
<div class="panel"><h3>🔥 V96 - Aqwam Mol3at = Atibba Lahziyin - 0/30 Dayman</h3><div class="ctrls"><div class="ctrl"><label>Capital $</label><input id="cap" type="number" value="1000" onchange="save()"></div><div class="ctrl"><label>Per Trade $</label><input id="per" type="number" value="100" onchange="save()"></div><div class="ctrl"><label>Target $</label><input id="targ" type="number" value="0.5" step="0.1" onchange="save()"><div style="font-size:12px;color:#facc15;font-family:'JetBrains Mono';direction:ltr" id="targVal">0.5$</div></div><div class="ctrl"><label>Hospital Cap (30)</label><input id="hcap" type="number" value="30" onchange="save()"></div></div></div>
<div class="header"><button class="hbtn orange" onclick="ctrl('try')">Dukhul</button><button class="hbtn yellow" onclick="ctrl('reset')">Reset</button><button class="hbtn red" onclick="ctrl('lock')">Lock -> Safi</button><button class="hbtn green" id="btnRun" onclick="ctrl('toggle')">Stop</button><button class="hbtn blue" onclick="ctrl('specialty')">Fak Zahma</button><button class="hbtn purple" onclick="ctrl('heal')">Shifa Kol</button><button class="hbtn cyan" id="btnDoc" onclick="ctrl('doctor')">Mol3a ON</button></div>
<div class="cards"><div class="c"><div class="l">Thabet</div><div class="v w" id="f1">1000$</div></div><div class="c ph"><div class="l">Pharmacy</div><div class="v r" id="f2">0.00$</div><div class="l" id="f2c">0 dawa</div></div><div class="c" style="border-color:#22c55e;box-shadow:0 0 15px #22c55e33"><div class="l">Safi Mohaqaq</div><div class="v g" id="f3" style="font-size:22px">+0$</div></div><div class="c gold"><div class="l">Ijmali</div><div class="v y" id="f5">1000$</div></div><div class="c"><div class="l">Ghair Mohaqaqa</div><div class="v g" id="f6">+0.00$</div></div></div>
<div class="table"><div class="thead" style="grid-template-columns:1.2fr 0.8fr 1.5fr 1fr 1fr 1fr 0.8fr"><div>Coin</div><div>Type</div><div>Status</div><div>Entry</div><div>Now</div><div>Profit $</div><div>%</div></div><div id="plist"></div></div>
<div class="table" style="border-color:#22d3ee"><div class="thead" style="grid-template-columns:1fr 1.5fr 0.8fr 0.8fr 0.8fr 1fr;background:#0e2a3a;color:#22d3ee"><div>Tabib Mol3a</div><div>Yoalej</div><div>Fatura</div><div>Hadaf</div><div>Ribh</div><div>Hala</div></div><div id="dlist"></div></div>
<div class="table" style="border-color:#fb923c"><div class="thead" style="grid-template-columns:1fr 1.5fr 0.8fr 0.8fr 0.8fr 1fr;background:#2a1f0f;color:#fb923c"><div>Mostashfa</div><div>Yoalej</div><div>Khassara</div><div>Hadaf</div><div>Hali</div><div>Nisba</div></div><div id="tlist"></div></div>
<div class="status"><span id="src">V96</span><span id="bin">...</span><span id="time">...</span></div>
<script>
async function ctrl(c){ await fetch('/api/control/'+c); load(); }
async function save(){ const cap=document.getElementById('cap').value, per=document.getElementById('per').value, targ=document.getElementById('targ').value, hcap=document.getElementById('hcap').value; const res=await fetch('/api/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({capital:cap,per_trade:per,target:parseFloat(targ),target_dollar:parseFloat(targ),hcap:hcap})}); const j=await res.json(); document.getElementById('targVal').innerText=j.config.target_dollar+'$'; }
async function load(){ try{ const r=await fetch('/api/data'); const d=await r.json(); document.getElementById('cap').value=d.config.capital; document.getElementById('per').value=d.config.per_trade; document.getElementById('targ').value=d.config.target_dollar; document.getElementById('hcap').value=d.config.hospital_cap; document.getElementById('elapsed').innerText=d.elapsed+'s'; document.getElementById('rate').innerText='V96 - '+d.treatment.length+'/'+d.config.hospital_cap; document.getElementById('profit').innerText='+'+d.doctor.profit.toFixed(2)+'$'; document.getElementById('healed').innerText=d.doctor.healed+' healed'; const bar=document.getElementById('docbar'); if(d.healing_mode){ bar.className='docbar heal'; document.getElementById('spec').innerText=d.doctor_positions.length+' MOL3A'; } else if(d.specialty){ bar.className='docbar spec'; document.getElementById('spec').innerText='ZAHMA '+d.treatment.length; } else { bar.className='docbar'; document.getElementById('spec').innerText=d.last_healed; } document.getElementById('f1').innerText=d.fixed.toFixed(2)+'$'; document.getElementById('f2').innerText=d.loss_pool.toFixed(2)+'$'; document.getElementById('f2c').innerText=d.treatment.length+' dawa'; document.getElementById('f3').innerText='+'+d.safi.toFixed(3)+'$'; document.getElementById('f5').innerText=d.total.toFixed(3)+'$'; let col=d.ghair>=d.config.target_dollar?'#22c55e':d.ghair>=0?'#facc15':'#38bdf8'; document.getElementById('f6').innerHTML='<span style="color:'+col+';font-family:JetBrains Mono">+'+d.ghair.toFixed(3)+'$</span> / '+d.config.target_dollar+'$'; document.getElementById('btnRun').innerText=d.is_running?'Stop':'Run'; document.getElementById('btnDoc').innerText=d.config.doctor_enabled?'Mol3a ON':'Mol3a OFF'; document.getElementById('src').innerText=d.data_source; document.getElementById('bin').innerText=d.binance_status; document.getElementById('time').innerText=new Date().toLocaleTimeString('en-US',{hour12:false}); let h=''; for(const p of d.positions){ let c=p[5]>=0?'#22c55e':'#38bdf8'; h+=`<div class="row" style="grid-template-columns:1.2fr 0.8fr 1.5fr 1fr 1fr 1fr 0.8fr"><div style="color:#fff;font-weight:900" class="num">${p[0]}</div><div><span class="badge blue">${p[1]}</span></div><div style="color:${c}" class="num">${p[6]}</div><div class="num">${p[2].toFixed(4)}</div><div class="num">${p[3].toFixed(4)}</div><div style="color:${c}" class="num">${p[4].toFixed(3)}$</div><div style="color:${c}" class="num">${p[5].toFixed(2)}%</div></div>` } document.getElementById('plist').innerHTML=h||'<div style="padding:12px;text-align:center;color:#94a3b8">Loading...</div>'; let dl=''; for(const p of d.doctor_positions){ let c=p[5]>=0?'#22d3ee':'#38bdf8'; dl+=`<div class="row" style="grid-template-columns:1fr 1.5fr 0.8fr 0.8fr 0.8fr 1fr;background:#0e1e2e"><div><span class="badge gold">${p[0]}</span></div><div style="color:#22d3ee;font-family:Cairo" class="num">${p[9]} Fatura ${p[8].toFixed(2)}$</div><div class="num" style="color:#fb923c">${p[8].toFixed(2)}$</div><div class="num" style="color:#facc15">${(p[8]+0.05).toFixed(2)}$</div><div class="num" style="color:${c}">${p[4].toFixed(3)}$</div><div class="num" style="color:${c}">${p[6]}</div></div>` } document.getElementById('dlist').innerHTML=dl||'<div style="padding:10px;text-align:center;background:#0e1e2e;color:#94a3b8">Doctors sleeping - 0/30</div>'; let t=''; for(const p of d.treatment){ t+=`<div class="row" style="grid-template-columns:1fr 1.5fr 0.8fr 0.8fr 0.8fr 1fr;background:#1a1500"><div><span class="badge orange">${p[0]}</span></div><div class="num" style="color:#facc15">${p[7]}</div><div class="num" style="color:#fb923c">-${p[8].toFixed(2)}$</div><div class="num" style="color:#facc15">${p[9].toFixed(2)}$</div><div class="num">${p[3].toFixed(4)}</div><div class="num">5%</div></div>` } document.getElementById('tlist').innerHTML=t||'<div style="padding:10px;text-align:center;background:#1a1500;color:#22c55e">Hospital empty 0/30 ✅</div>'; }catch(e){} } setInterval(load,1000); load();
</script></body></html>"""
